import { useMutation, type UseMutationOptions } from "@tanstack/react-query";
import { updateSpaceFiles } from "../handlers/updateSpaceFiles";
import type { ApiError } from "../runtime/client";
import type { SpacePartition } from "../types/SpacePartition";
import type { UpdateSpaceFilesRequest } from "../types/UpdateSpaceFilesRequest";

type Data = Awaited<ReturnType<typeof updateSpaceFiles>>;
type Vars = { spacePk: SpacePartition; req: UpdateSpaceFilesRequest };

export function useUpdateSpaceFiles(
  options?: Omit<UseMutationOptions<Data, ApiError, Vars>, "mutationFn">,
) {
  return useMutation<Data, ApiError, Vars>({
    mutationFn: (vars) => updateSpaceFiles(vars.spacePk, vars.req),
    ...options,
  });
}
